IF NOT EXISTS (SELECT 1 FROM sys.tables t JOIN sys.schemas s ON t.schema_id = s.schema_id WHERE s.name = 'dbo' AND t.name = 'devices') CREATE TABLE dbo.devices (device_id NVARCHAR(64) NOT NULL PRIMARY KEY, device_name NVARCHAR(128) NULL, location_code NVARCHAR(64) NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
IF NOT EXISTS (SELECT 1 FROM sys.tables t JOIN sys.schemas s ON t.schema_id = s.schema_id WHERE s.name = 'dbo' AND t.name = 'telemetry_samples') CREATE TABLE dbo.telemetry_samples (sample_id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, device_id NVARCHAR(64) NOT NULL, metric_name NVARCHAR(64) NOT NULL, metric_value FLOAT NOT NULL, event_time DATETIME2 NOT NULL, ingest_time DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), source_type NVARCHAR(16) NOT NULL, CONSTRAINT FK_telemetry_samples_devices FOREIGN KEY (device_id) REFERENCES dbo.devices(device_id));
